import type { InputAction } from './input-handler'

/**
 * The keymap is the single source of truth for normal-mode keyboard shortcuts.
 *
 * It drives four things that used to be maintained (and drift) separately:
 *   1. dispatch        — the input handler looks up the pressed key here
 *   2. the `?` overlay — rendered from {@link getHelpGroups}
 *   3. the footer hint — rendered from {@link getFooterHints}
 *   4. the README      — generated by {@link renderReadmeKeyTable}
 *
 * Add a binding once and all four stay correct.
 */

export type KeyGroup = 'Navigation' | 'Selection' | 'Filtering' | 'View'

/** Group display order for the help overlay and README. */
export const KEY_GROUPS: KeyGroup[] = ['Navigation', 'Selection', 'Filtering', 'View']

export interface KeyBinding {
  /**
   * readline `key.name` tokens that trigger {@link action}. Shifted letters are
   * normalized to uppercase tokens (see {@link findBinding}). Omit for keys the
   * input handler resolves specially (e.g. `/`, `!`, `?`, Enter, Esc).
   */
  tokens?: string[]
  /** Action dispatched when a token matches. Omit for display-only entries. */
  action?: InputAction
  /** How the key is shown in the help overlay and README, e.g. '↑ / k'. */
  displayKeys: string
  /** Full description shown in the help overlay and README. */
  help: string
  group: KeyGroup
  /** Short footer hint; omit to keep the key out of the compact footer line. */
  footer?: { keyLabel: string; label: string }
}

