/**
 * Resolve a pressed key token to its binding. Tries an exact match first so the
 * case-sensitive vim pair `g`/`G` is honored, then falls back to the lowercase
 * letter so shifted letters (e.g. `M`) still trigger their lowercase binding.
 */
export function findBinding(token: string): KeyBinding | undefined {
  const exact = KEY_BINDINGS.find((binding) => binding.tokens?.includes(token))
  if (exact) return exact
  if (/^[A-Z]$/.test(token)) {
    const lower = token.toLowerCase()
    return KEY_BINDINGS.find((binding) => binding.tokens?.includes(lower))
  }
  return undefined
}

// Computed once at module load — KEY_BINDINGS is static so these never change.
const _footerHints: Array<{ keyLabel: string; label: string }> = KEY_BINDINGS.flatMap((binding) =>
  binding.footer ? [binding.footer] : []
)
const _helpGroups: Array<{ group: KeyGroup; bindings: KeyBinding[] }> = KEY_GROUPS.map((group) => ({
  group,
  bindings: KEY_BINDINGS.filter((b) => b.group === group),
})).filter((entry) => entry.bindings.length > 0)

/** Curated short hints for the compact footer line, in display order. */
export function getFooterHints(): Array<{ keyLabel: string; label: string }> {
  return _footerHints
}

/** Bindings grouped for the `?` help overlay, preserving {@link KEY_GROUPS} order. */
export function getHelpGroups(): Array<{ group: KeyGroup; bindings: KeyBinding[] }> {
  return _helpGroups
}

/**
 * Render the README "Keyboard Shortcuts" markdown table from the keymap. This is
 * the body placed between the `<!-- KEYS:START -->`/`<!-- KEYS:END -->` markers;
 * a test fails if the README drifts from it (see keymap-readme.test.ts).
 */
export function renderReadmeKeyTable(): string {
  const rows = KEY_BINDINGS.map((binding) => `| \`${binding.displayKeys}\` | ${binding.help} |`)
  return ['| Key | Action |', '|-----|--------|', ...rows].join('\n')
}
